// TH16 v1.00a st06bs.ecl.txt
//   entry    Boss1     lines 88-111  (first stage-6 boss nonspell)
//   dependency Boss1_at lines 113-184
// The boss fires four 4-way kunai rings (colors 6/14/4/10) from four rotating
// base angles, and drifts with moveRand between bursts. Omitted per policy:
// lifeMarker(0,2400,-24448), stars(5), anm* and playSound (presentation);
// timerReset/setInterrupt are represented by the phase timer and SRC_LIMIT.

const TIME_LIMIT: int = 2284;     // 120 opening buffer + 2160 source window + 4
const OPENING_BUFFER: int = 120;
const SRC_LIMIT: int = 2160;      // Boss1:91 setInterrupt(0, 2400, 2160, "BossCard1")

const BOSS_X: fx = 0fx;           // Boss:14 movePos(0.0f, 128.0f)
const BOSS_Y: fx = 128fx;
const BOSS_HP: int = 17400;       // Boss:22 lifeSet(17400)

// Boss1:94 moveLimit(0.0f, 128.0f, 280.0f, 8.0f); x/y are full width/height.
// Direction choice in moveRand uses the centre +/- 1/4 of width/height.
const LIM_X0: fx = -140fx;
const LIM_X1: fx = 140fx;
const LIM_Y0: fx = 124fx;
const LIM_Y1: fx = 132fx;
const IN_X: fx = 70fx;
const IN_Y0: fx = 126fx;
const IN_Y1: fx = 130fx;

// Boss:29-30 setHurtbox(56,56) / setHitbox(50,50), circle branch: first value * 0.5
const BODY_R: fx = 25fx;
const HURT_R: fx = 28fx;

// Boss1_at:116-150 emitter sprites and etDist values
const COL_A: int = 6;    // etSprite(0, 9, 6)
const COL_B: int = 14;   // etSprite(1, 9, 14)
const COL_C: int = 4;    // etSprite(2, 9, 4)
const COL_D: int = 10;   // etSprite(3, 9, 10)
const DIST_A: fx = 64fx; // etDist(0, 64.0f), copied to emitter 1
const DIST_B: fx = 24fx; // etDist(2, 24.0f), etDist(3, 24.0f)
const RAMP_FRAMES: int = 120; // Boss1_at:141 etEx type 0x200000 a=120

// Source EX record 1: type 0x200000 (VELTIME), a=120, r=2.0/2.5, s=-999999
// (below -999990, so the bullet keeps its current angle). The scalar speed
// rises by delta=(r-s0)/120 per frame along that fixed direction.
xformdef VEL_RAMP(delta: fx) {
    set_gravity(at_spawn(delta * cos($self_angle)), at_spawn(delta * sin($self_angle)));
    wait(RAMP_FRAMES);
    set_gravity(0fx, 0fx);
}

// moveRand step arming, per movement.md recipe generalised to this card's
// limit box and duration/start speed.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var dur: int = self_int(1);
    var speed: fx = 0fx;
    if k < dur { speed = self_fx(2) * ((dur - k) as fx) / (dur as fx); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < LIM_X0 { nx = LIM_X0; }
    if nx > LIM_X1 { nx = LIM_X1; }
    if ny < LIM_Y0 { ny = LIM_Y0; }
    if ny > LIM_Y1 { ny = LIM_Y1; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

// One source frame: wait, advance the source clock, arm the next movement tick.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        set_self_int(2, self_int(2) + 1);
        card_arm_next_step();
    }
}

// moveRand(frames, angleMode, speed): direction sampled once per call from the
// current position, then a linear speed decay; angleMode has no documented
// target-side effect (verified sample: fixed direction, mode0 speed slot).
sub move_rand_begin(dur: int, speed: fx) {
    set_self_int(1, dur);
    set_self_fx(2, speed);
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -IN_X {
        a = r / 3;
    } else if $self_x > IN_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < IN_Y0 {
        if a < 0 { a = -a; }
    } else if $self_y > IN_Y1 {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Boss1_at: loop body firing all four emitters, then the difficulty wait.
sub boss1_at() {
    var rank: int = global(GVAR_RANK);
    var e_bam: int = 3deg as int;   // diffF %E: E 10deg / N 5deg / H 4deg / L 3deg
    var w: int = 3;                 // !LO wait value
    var shots: int = 61;            // diffI $F: E 24 / N 48 / H 61 / L 61
    if rank == RANK_EASY { e_bam = 10deg as int; w = 10; shots = 24; }
    else if rank == RANK_NORMAL { e_bam = 5deg as int; w = 5; shots = 48; }
    else if rank == RANK_HARD { e_bam = 4deg as int; w = 4; shots = 61; }
    var a0: int = 0;
    var a1: int = 0;
    var a2: int = 0;
    var a3: int = 0;
    for i in 0..shots {
        if self_int(2) >= SRC_LIMIT { return; }
        // Boss1_at:159-166 etAngle/etOn 0..3
        sh_angle(0, a0 as angle, 0deg); sh_fire(0);
        sh_angle(1, a1 as angle, 0deg); sh_fire(1);
        sh_angle(2, a2 as angle, 0deg); sh_fire(2);
        sh_angle(3, a3 as angle, 0deg); sh_fire(3);
        // Boss1_at:167-170 A += E; B -= E; C += 2E; D -= 2E
        a0 = a0 + e_bam;
        a1 = a1 - e_bam;
        a2 = a2 + 2 * e_bam;
        a3 = a3 - 2 * e_bam;
        // Boss1_at:171-180 difficulty wait
        card_wait(w);
    }
}

async sub boss_task() {
    set_invuln(65535);
    set_hitbox(BODY_R);
    set_hurtbox(HURT_R);
    set_self_int(0, 0);   // movement step count
    set_self_int(1, 0);   // movement duration
    set_self_int(2, 0);   // source frame clock
    set_self_fx(0, 0fx);  // direction cos
    set_self_fx(1, 0fx);  // direction sin
    set_self_fx(2, 0fx);  // movement start speed
    var rank: int = global(GVAR_RANK);
    // Boss1_at:121-141 initial speed s0 and VELTIME target r
    var s0: fx = 2.4fx;
    var vmax: fx = 2.5fx;
    if rank == RANK_EASY { s0 = 1.7fx; vmax = 2.0fx; }
    else if rank == RANK_NORMAL { s0 = 1.7fx; vmax = 2.0fx; }
    else if rank == RANK_HARD { s0 = 1.9fx; vmax = 2.0fx; }
    var delta: fx = (vmax - s0) / 120fx;
    // etDist minus ANIM entry offset position -= 4*velocity
    var dist_a: fx = DIST_A - 4fx * s0;
    var dist_b: fx = DIST_B - 4fx * s0;

    // etNew 0 + config; emitters 1..3 copy emitter 0 and only change sprite/dist
    sh_reset(0);
    sh_sprite(0, TH16_KUNAI, COL_A);
    sh_ring(0, 1);
    sh_count(0, 4, 1);
    sh_speed(0, s0, 0fx);
    sh_dist(0, dist_a);
    sh_xform(0, VEL_RAMP(delta));

    sh_reset(1);
    sh_sprite(1, TH16_KUNAI, COL_B);
    sh_ring(1, 1);
    sh_count(1, 4, 1);
    sh_speed(1, s0, 0fx);
    sh_dist(1, dist_a);
    sh_xform(1, VEL_RAMP(delta));

    sh_reset(2);
    sh_sprite(2, TH16_KUNAI, COL_C);
    sh_ring(2, 1);
    sh_count(2, 4, 1);
    sh_speed(2, s0, 0fx);
    sh_dist(2, dist_b);
    sh_xform(2, VEL_RAMP(delta));

    sh_reset(3);
    sh_sprite(3, TH16_KUNAI, COL_D);
    sh_ring(3, 1);
    sh_count(3, 4, 1);
    sh_speed(3, s0, 0fx);
    sh_dist(3, dist_b);
    sh_xform(3, VEL_RAMP(delta));

    // Boss1:99 wait(60) (anmPlay/playSound around it are presentation)
    card_wait(60);

    loop {
        if self_int(2) >= SRC_LIMIT { break; }
        move_rand_begin(240, 0.5fx);   // Boss1:104
        boss1_at();                    // Boss1:105
        if self_int(2) >= SRC_LIMIT { break; }
        move_rand_begin(60, 1.9fx);    // Boss1:106
        card_wait(60);                 // Boss1:107
    }
    // main task return = real enemy leaves (source interrupt at 2160)
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(BOSS_X, BOSS_Y, BOSS_HP, 0, 0, 0, boss_task);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

